package seeders

import (
	"context"
	"fmt"

	"github.com/vuepher/vuepher/orm"

	"blog/app/models"
	"blog/database/factories"
)

// PostSeeder seeds the database with generated posts.
//
// Generated by `vuepher make:seeder PostSeeder`, then filled in.
//
// Register it in database/seeders/registry.go and run it with
// `vuepher db:seed PostSeeder`.
// Seeders must be safe to run against a development database that already has
// data, so the insert only happens when the table is empty.
type PostSeeder struct {
}

// Run inserts the seed data.
func (PostSeeder) Run(ctx context.Context, db *orm.DB) error {
	// A factory keeps the generated values in one place and lets a test reuse
	// them with a different count.
	existing, err := orm.QueryOn[models.Post](db).Context(ctx).Count()
	if err != nil {
		return err
	}
	if existing > 0 {
		fmt.Printf("skipped: %d posts already exist\n", existing)
		return nil
	}

	records, err := factories.NewPostFactory(20).CreateWith(ctx, db)
	if err != nil {
		return err
	}
	fmt.Printf("seeded: %d posts\n", len(records))
	return nil
}
